/** Return a curated look for a typed name, or undefined if unknown. */
export function getCelebrityLook(name: string): string | undefined {
  const key = name.trim().toLowerCase();
  if (!key) return undefined;
  if (CELEBRITY_LOOKS[key]) return CELEBRITY_LOOKS[key];
  const folded = key.normalize("NFD").replace(/\p{M}/gu, "");
  for (const [k, v] of Object.entries(CELEBRITY_LOOKS)) {
    const kf = k.normalize("NFD").replace(/\p{M}/gu, "");
    if (kf === folded) return v;
  }
  return undefined;
}
